/// Join a module's three ordered parts — leading doc-comment, import block, body — into the ONE
/// canonical shape every materialized module takes:
///
/// ```text
/// <module doc-comment>
///                          (one blank, when a doc-comment precedes anything)
/// import ...;              (the block, one statement per line)
///                          (one blank, when the block precedes a body)
/// <body>
/// ```
///
/// `head` and `block` each already carry their own trailing newline when non-empty, so this only
/// supplies the single blank SEPARATORS — and omits a separator whenever the part beside it is empty.
/// It is the exact inverse of [`crate::imports_fmt::split_head`] + [`crate::imports_fmt::strip_imports`], which is what lets the NORMALIZE
/// pass and the EMITTER produce byte-identical output by CONSTRUCTION rather than by agreement.
pub fn layout(head: &str, block: &str, body: &str) -> String {
    let mut out = String::with_capacity(head.len() + block.len() + body.len() + 2);
    out.push_str(head);
    if !head.is_empty() && (!block.is_empty() || !body.is_empty()) {
        out.push('\n');
    }
    out.push_str(block);
    if !block.is_empty() && !body.is_empty() {
        out.push('\n');
    }
    out.push_str(body);
    out
}
